#!/system/bin/sh

if [ "$(id -u)" != "0" ]; then
    echo "O mod precisa ser executado como root."
    exec su -c "sh '$0' '$@'"
fi

TARGET="/data/local/tmp/zig_liberdade_exec"
LOG="/data/local/tmp/overlay.log"
PKG="com.dts.freefireth"
KEY_FILE="/data/local/tmp/key.txt"

# Garante que o arquivo de chave exista com uma Random Key valida
if [ ! -f "$KEY_FILE" ] || [ ! -s "$KEY_FILE" ]; then
    RAND_HEX=$(head -c 8 /dev/urandom 2>/dev/null | od -A n -t x1 2>/dev/null | tr -d ' \n')
    [ -z "$RAND_HEX" ] && RAND_HEX="RAND$RANDOM$RANDOM"
    RAND_KEY="VIP-${RAND_HEX}"
    echo -n "$RAND_KEY" > "$KEY_FILE"
    chmod 666 "$KEY_FILE"
    echo "Random Key gerada e configurada: $RAND_KEY"
else
    echo "Usando chave existente em $KEY_FILE: $(cat $KEY_FILE)"
fi

echo "Extraindo e preparando o binário..."

# Extrai o payload em Base64 do próprio script e decodifica direto no destino
if ! sed '1,/^__PAYLOAD__$/d' "$0" | base64 -d > "$TARGET"; then
    echo "Erro: falha ao extrair ou decodificar o binário."
    rm -f "$TARGET"
    exit 1
fi

if ! chmod 755 "$TARGET"; then
    echo "Erro: não foi possível tornar o binário executável."
    rm -f "$TARGET"
    exit 1
fi

echo "Iniciando overlay..."

# Inicialização isolada e segura em background
setsid nohup "$TARGET" > "$LOG" 2>&1 </dev/null &
disown

# Dar um momento para inicializar
sleep 1

echo "Iniciando Free Fire..."

monkey -p "$PKG" \
    -c android.intent.category.LAUNCHER \
    1 >/dev/null 2>&1

if [ $? -eq 0 ]; then
    echo "Free Fire iniciado corretamente."
else
    echo "Não foi possível iniciar o Free Fire. Tentando via Activity Manager..."

    ACTIVITY="$(cmd package resolve-activity --brief "$PKG" 2>/dev/null | tail -n 1)"

    if [ -n "$ACTIVITY" ]; then
        am start -n "$ACTIVITY"
    else
        echo "Nenhuma atividade de início foi encontrada."
    fi
fi

echo "Log do overlay: $LOG"
exit 0

__PAYLOAD__

